package studio.parasite.home;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;
public class HomeActivity extends Activity {
 private int touches=0;private long lastTouch=0;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER);root.setPadding(28,28,28,28);root.setBackgroundColor(Color.rgb(7,12,9));TextView heading=new TextView(this);heading.setText("parasite");heading.setTextSize(54);heading.setTextColor(Color.rgb(166,238,133));heading.setGravity(Gravity.CENTER);root.addView(heading);TextView label=new TextView(this);label.setText("INSTRUMENT OPERATING ENVIRONMENT");label.setTextSize(11);label.setLetterSpacing(.2f);label.setTextColor(Color.rgb(140,165,142));label.setGravity(Gravity.CENTER);root.addView(label);TextView hint=new TextView(this);hint.setText("INSTRUMENT HUB");hint.setTextColor(-1);hint.setTextSize(18);hint.setGravity(Gravity.CENTER);root.addView(hint);Button open=new Button(this);open.setText("OPEN PARASITE");root.addView(open);open.setOnClickListener(v->launchHub());Button update=new Button(this);update.setText("CHECK FOR UPDATES");root.addView(update);update.setOnClickListener(v->launchHub());TextView foot=new TextView(this);foot.setText("PARASITE OS 1.0");foot.setTextColor(Color.GRAY);foot.setPadding(0,35,0,0);foot.setGravity(Gravity.CENTER);root.addView(foot);foot.setOnClickListener(v->{long now=System.currentTimeMillis();if(now-lastTouch>1800)touches=0;lastTouch=now;if(++touches>=7){touches=0;new AlertDialog.Builder(this).setTitle("Maintenance").setMessage("Open Android settings? This is a recovery route; Amazon firmware remains installed.").setPositiveButton("Open",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_SETTINGS))).setNegativeButton("Cancel",null).show();}});setContentView(root);}
 private void launchHub(){try{Intent i=getPackageManager().getLaunchIntentForPackage("studio.transform.launcher");if(i!=null){startActivity(i);return;}}catch(Exception ignored){}new AlertDialog.Builder(this).setMessage("Existing Parasite Hub not found. Reinstall it or open maintenance settings.").setPositiveButton("OK",null).show();}
 @Override public void onBackPressed(){}
}
